@@ -0,0 +1,10 @@
+import { buildOrganizerDigest } from "./digest.js";
+import { paginate } from "../lib/collections.js";
+
+export function buildDashboard(events, signupsByEvent, query = {}) {
+  const { search, page = 1, pageSize = 10 } = query ?? {};
+  const needle = String(search ?? "").trim().toLowerCase();
+  const digest = buildOrganizerDigest(events, signupsByEvent);
+  const matches = needle ? digest.filter((item) => item.title.toLowerCase().includes(needle)) : digest;
+  return paginate(matches, page, pageSize);
+}
